// Situação ao vivo em dois gráficos:
// 1) idade do estoque: valor (saldo × custo médio) por tempo desde o último movimento do produto no projeto (entrada ou baixa);
// 2) composição da custódia: estoque em projetos ativos, em projetos encerrados e materiais aguardando vínculo.
const SITUACAO_DIAS=30;
const IDADE_FAIXAS=[[0,30,'até 30 dias','#bfdbfe'],[31,60,'31 a 60 dias','#60a5fa'],[61,90,'61 a 90 dias','#2563eb'],[91,1e9,'mais de 90 dias','#1e3a8a']];
const CUSTODIA_CORES={ativos:'#2563eb',encerrados:'#d97706',aguardando:'#9333ea'};
function situacaoDados(clientes,pend){const ult=new Map(),hoje=Date.now();const marca=(k,d)=>{if(/^\d{4}-\d{2}-\d{2}$/.test(d||'')&&(!ult.has(k)||d>ult.get(k)))ult.set(k,d)};
 for(const a of state.allocations){const inv=state.invoices.find(i=>i.id===a.invoiceId);if(inv&&!isServico(inv))marca(a.projectId+'|'+a.productId,String(inv.date||'').slice(0,10))}
 for(const m of state.movements)if(m.type==='SAIDA')marca(m.projectId+'|'+m.productId,String(m.date||'').slice(0,10));
 const faixas=IDADE_FAIXAS.map(f=>({rot:f[2],cor:f[3],min:f[0],max:f[1],valor:0,itens:[]}));let ativos=0,encerrados=0;const encList=[];
 for(const x of clientes)for(const y of x.projetos){if(y.p.status==='encerrado'){encerrados+=y.tot.estoque;if(y.tot.estoque>0.005)encList.push({y,c:x.c})}else ativos+=y.tot.estoque;
  for(const l of y.itens){if(l.saldo<=1e-9||l.estoque<=0.005)continue;const d=ult.get(y.p.id+'|'+l.productId);const dias=d?Math.max(0,Math.floor((hoje-new Date(d+'T12:00:00'))/864e5)):0;const f=faixas.find(f=>dias>=f.min&&dias<=f.max);f.valor+=l.estoque;f.itens.push({nome:l.nome,proj:y.p.name,cli:x.c.name,dias,valor:l.estoque})}}
 faixas.forEach(f=>f.itens.sort((a,b)=>b.valor-a.valor));
 return {faixas,custodia:[{k:'ativos',rot:'Em projetos ativos',v:ativos},{k:'encerrados',rot:'Em projetos encerrados',v:encerrados},{k:'aguardando',rot:'Aguardando vínculo',v:pend.pago}],encList}}
function graficoIdade(faixas){const W=760,H=200,L=12,R=12,T=26,B=40,pw=W-L-R,ph=H-T-B,n=faixas.length,gap=18,bw=(pw-gap*(n-1))/n,max=Math.max(1,...faixas.map(f=>f.valor));
 const barras=faixas.map((f,i)=>{const h=f.valor>0?Math.max(4,f.valor/max*ph):0,x=L+i*(bw+gap),y=T+ph-h;const top=f.itens.slice(0,4).map(t=>`${t.nome} · ${t.proj}: ${money(t.valor)} (${t.dias} dias)`).join('\n');
  return `<g class="barra-hit"><title>${esc(f.rot)}: ${money(f.valor)} em ${f.itens.length} item(ns)${top?'\n'+esc(top):''}</title><rect x="${x.toFixed(1)}" y="${T}" width="${bw.toFixed(1)}" height="${ph}" fill="transparent"/>${h?`<path d="M${x.toFixed(1)},${(T+ph).toFixed(1)}V${(y+4).toFixed(1)}q0,-4 4,-4H${(x+bw-4).toFixed(1)}q4,0 4,4V${(T+ph).toFixed(1)}Z" fill="${f.cor}"/>`:''}<text x="${(x+bw/2).toFixed(1)}" y="${(y-8).toFixed(1)}" text-anchor="middle" class="graf-valor">${moneyC(f.valor)}</text><text x="${(x+bw/2).toFixed(1)}" y="${H-20}" text-anchor="middle" class="graf-eixo">${esc(f.rot)}</text><text x="${(x+bw/2).toFixed(1)}" y="${H-6}" text-anchor="middle" class="graf-eixo2">${f.itens.length} item(ns)</text></g>`}).join('');
 return `<svg viewBox="0 0 ${W} ${H}" class="graf" role="img" aria-label="Valor em estoque por tempo sem movimento"><line x1="${L}" x2="${W-R}" y1="${T+ph}" y2="${T+ph}" class="graf-base"/>${barras}</svg>`}
function graficoCustodia(partes){const tot=partes.reduce((s,p)=>s+p.v,0);if(tot<=0.005)return '<p class="hint">Nada sob custódia.</p>';const W=470,H=60,Y=18,BH=28;let x=0;const vis=partes.filter(p=>p.v>0.005);
 const seg=vis.map((p,i)=>{const w=p.v/tot*W;const g=i<vis.length-1?2:0;const r=`<g class="barra-hit"><title>${esc(p.rot)}: ${money(p.v)} (${fmtPct(pct(p.v,tot))})</title><rect x="${x.toFixed(1)}" y="${Y}" width="${Math.max(1,w-g).toFixed(1)}" height="${BH}" rx="${i===0||i===vis.length-1?4:0}" fill="${CUSTODIA_CORES[p.k]}"/>${w>70?`<text x="${(x+w/2).toFixed(1)}" y="${Y+BH/2+4}" text-anchor="middle" class="graf-dentro">${fmtPct(pct(p.v,tot))}</text>`:''}</g>`;x+=w;return r}).join('');
 const leg=partes.map(p=>`<span title="${esc(p.rot)}"><span class="sw" style="background:${CUSTODIA_CORES[p.k]}"></span>${esc(p.rot)} <strong>${money(p.v)}</strong></span>`).join('');
 return `<div class="legend-inline" style="margin-bottom:4px">${leg}</div><svg viewBox="0 0 ${W} ${H}" class="graf" role="img" aria-label="Composição do valor sob custódia">${seg}<text x="0" y="12" class="graf-eixo" text-anchor="start">custódia total ${money(tot)}</text></svg>`}
function situacaoAoVivo(clientes,pend){const d=situacaoDados(clientes,pend);const parados=d.faixas.filter(f=>f.min>=SITUACAO_DIAS+1).flatMap(f=>f.itens).sort((a,b)=>b.valor-a.valor);
 const tabelaIdade=`<details class="tl-tab"><summary>Ver os itens por faixa (tabela)</summary><div class="tablewrap" style="margin-top:8px"><table class="no-sort"><thead><tr><th>Faixa</th><th>Produto</th><th>Projeto</th><th class="num">Dias sem movimento</th><th class="num">Valor em estoque</th></tr></thead><tbody>${d.faixas.flatMap(f=>f.itens.map(t=>`<tr><td>${esc(f.rot)}</td><td>${esc(t.nome)}</td><td>${esc(t.proj)}<div class="hint">${esc(t.cli)}</div></td><td class="num">${t.dias}</td><td class="num">${money(t.valor)}</td></tr>`)).join('')||'<tr><td colspan="5" class="muted">Sem estoque nos projetos.</td></tr>'}</tbody></table></div></details>`;
 const tabelaCust=`<details class="tl-tab"><summary>Ver os valores (tabela)</summary><div class="tablewrap" style="margin-top:8px"><table class="no-sort"><tbody>${d.custodia.map(p=>`<tr><td>${esc(p.rot)}</td><td class="num">${money(p.v)}</td></tr>`).join('')}${d.encList.map(x=>`<tr><td class="hint">↳ ${esc(x.y.p.name)} · ${esc(x.c.name)} (encerrado)</td><td class="num">${money(x.y.tot.estoque)}</td></tr>`).join('')}</tbody></table></div></details>`;
 return `<div class="dash-grid" style="margin-bottom:16px"><div class="panel"><div class="ph"><h3 title="Valor em estoque (saldo × custo médio) agrupado pelo tempo desde a última entrada ou baixa do produto no projeto">Idade do estoque: tempo sem movimento</h3>${parados.length?`<button class="btn sm" data-go="stock" title="Abre o saldo por cliente e projeto para registrar as saídas">Ver estoque</button>`:''}</div>${graficoIdade(d.faixas)}<p class="hint">${parados.length?`${money(parados.reduce((s,t)=>s+t.valor,0))} parados há mais de ${SITUACAO_DIAS} dias, em ${parados.length} item(ns). O maior: ${esc(parados[0].nome)} (${esc(parados[0].proj)}).`:`Nenhum item parado há mais de ${SITUACAO_DIAS} dias.`}</p>${tabelaIdade}</div>
 <div class="panel"><div class="ph"><h3 title="Tudo o que está sob custódia, ainda não apropriado como custo">Composição da custódia</h3>${pend.pago>0.005?'<button class="btn sm" data-go="invoices" title="Abre as notas a vincular">Vincular notas</button>':''}</div>${graficoCustodia(d.custodia)}<p class="hint">${d.encList.length?`${d.encList.length} projeto(s) encerrado(s) ainda com material: dar baixa, devolver ou transferir.`:'Nenhum projeto encerrado com saldo.'}${pend.pago>0.005?` ${pend.notas} nota(s) de materiais aguardando vínculo.`:''}</p>${tabelaCust}</div></div>`}
function renderDashMore(pend,pendServ={valor:0}){const lista=state.invoices.filter(i=>invoiceStatus(i)!=='vinculada');$('#dashPendingSum').innerHTML=lista.length?`<span class="pill warn">${lista.length}</span> ${money(pend.pago+pendServ.valor)} fora do total`:'· nenhuma';if(lista.length)$('#dashPending').open=true;$('#dashPendingList').innerHTML=lista.length?`<div class="tablewrap"><table class="no-sort"><thead><tr><th>Tipo</th><th>Data</th><th>NF</th><th>Emitente / prestador</th><th>Situação</th><th>Distribuição</th><th></th></tr></thead><tbody>${lista.map(i=>{const st=invoiceStatus(i);return `<tr><td>${tipoPill(i)}</td><td>${esc(i.date)}</td><td>${esc(i.number)}</td><td>${esc(i.issuer)}</td><td><span class="pill ${st==='a_vincular'?'warn':'blue'}">${STATUS_LABEL[st]}</span></td><td>${distBar(invoiceShares(i))}</td><td><button class="btn sm primary" data-open-invoice-go="${esc(i.id)}">${st==='a_vincular'?'Vincular':'Distribuir'}</button></td></tr>`}).join('')}</tbody></table></div>`:tableEmpty('Todas as notas estão vinculadas.');
 const qs=[...state.quotes].sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt)));$('#dashQuotesSum').textContent=qs.length?'· '+qs.length+' gerado(s)':'· nenhum';$('#dashQuotes').innerHTML=qs.length?`<div class="tablewrap"><table class="no-sort"><thead><tr><th>Pedido</th><th>Data</th><th>Fornecedor</th><th>Cliente · projeto</th><th class="num">Itens</th></tr></thead><tbody>${qs.slice(0,8).map(q=>`<tr><td><strong>${esc(q.number)}</strong></td><td>${esc(q.date)}</td><td>${esc(q.supplier?.name)}</td><td>${q.projectId?esc(projectLabel(projectById(q.projectId))):'—'}</td><td class="num">${q.items.length}</td></tr>`).join('')}</tbody></table></div>`:tableEmpty('Nenhum pedido de orçamento gerado.')}
function tableEmpty(s){return '<p class="muted">'+s+'</p>'}
function render(){renderDashboard();renderStock();renderInvoices();renderSuppliers();renderProducts();renderRecent();renderClients();renderQuoteHistory();quoteSolicitantePreencher();renderEscopoPanel();nuvemRender();acessosRender();filaSincronizar();renderSubnav($('.view.active')?.id)}
// ---------- Saída (consumo) por projeto × produto ----------
function saldoProjeto(pid,prod){const ent=state.allocations.filter(a=>a.projectId===pid&&a.productId===prod).reduce((s,a)=>s+Number(a.quantity),0);const sai=state.movements.filter(m=>m.type==='SAIDA'&&m.projectId===pid&&m.productId===prod).reduce((s,m)=>s+Number(m.quantity),0);return r4(ent-sai)}
function openSaidaForm(key){document.querySelectorAll('.saida-form').forEach(x=>x.remove());const row=document.querySelector(`[data-prod-row="${CSS.escape(key)}"]`);if(!row)return;const [pid,prod]=key.split('|');const p=state.products.find(x=>x.id===prod),saldo=saldoProjeto(pid,prod);const tr=document.createElement('tr');tr.className='saida-form';tr.dataset.saidaKey=key;
 tr.innerHTML=`<td colspan="8"><div class="row" style="align-items:flex-end"><strong style="align-self:center">Saída de ${esc(p?.name||'produto')} · ${esc(projectLabel(projectById(pid)))}</strong><div class="field" style="max-width:130px;min-width:110px"><label>Quantidade (máx. ${num(saldo)})</label><input type="number" min="0" step="any" max="${saldo}" data-sf="qtd"></div><div class="field" style="max-width:170px"><label>Data</label><input type="date" data-sf="data" value="${new Date().toISOString().slice(0,10)}"></div><div class="field"><label>Destino / observação</label><input data-sf="obs" placeholder="Ex.: entregue na turma A"></div><button class="btn primary" data-saida-ok title="Baixa o material do estoque e apropria o custo (quantidade × custo médio) ao projeto">Confirmar saída</button><button class="btn" data-saida-cancel>Cancelar</button></div><div data-sf="msg"></div></td>`;row.after(tr);tr.querySelector('[data-sf="qtd"]').focus()}
async function confirmSaida(tr){const [pid,prod]=tr.dataset.saidaKey.split('|');const qtd=Number(String(tr.querySelector('[data-sf="qtd"]').value).replace(',','.')),data=tr.querySelector('[data-sf="data"]').value,obs=tr.querySelector('[data-sf="obs"]').value.trim();const msg=h=>tr.querySelector('[data-sf="msg"]').innerHTML=`<div class="notice danger">${h}</div>`;const saldo=saldoProjeto(pid,prod);
 if(!(qtd>0)){msg('Informe uma quantidade maior que zero.');return}if(qtd>saldo+1e-9){msg(`A quantidade passa do saldo do projeto (${num(saldo)}).`);return}if(!data){msg('Informe a data.');return}
 const proj=projectById(pid),p=state.products.find(x=>x.id===prod);const linha=stockTree().clientes.flatMap(c=>c.projetos).find(x=>x.p.id===pid)?.itens.find(l=>l.productId===prod);
 await txWrite(['movements','products'],os=>{os.movements.add({id:uid(),type:'SAIDA',productId:prod,projectId:pid,clientId:proj?.clientId||'',quantity:r4(qtd),unitCost:linha?.custo||0,date:data,note:obs,description:p?.name||'',createdAt:new Date().toISOString()});if(p)os.products.put({...p,stock:r4(Number(p.stock||0)-qtd)})});
 await refresh()}
// ---------- Grid hierárquica: cliente → projeto → produto ----------
const collapsedClients=new Set(), openProjects=new Set();
function emptyTot(){return {entrada:0,saida:0,pago:0,estoque:0,serv:0}}
// ==== #JS-CUSTODIA: START ====
// Conceitos: o material entra no ESTOQUE (valor sob custódia, ainda não é custo) e só vira CUSTO APROPRIADO ao cliente e ao projeto
// na baixa (saída), pelo custo médio. O serviço não passa pelo estoque: vira custo apropriado quando a nota é vinculada.
// Total adquirido = estoque + custo apropriado. Nos totais (emptyTot): pago = valor de entrada dos materiais, estoque = saldo × custo médio.
const materiaisBaixados=t=>Math.max(0,t.pago-t.estoque);
const custoApropriado=t=>materiaisBaixados(t)+(t.serv||0);
const totalAdquirido=t=>t.pago+(t.serv||0);
const COR_APROPRIADO='#0f766e';
const ROTULO={estoque:'Em estoque (sob custódia)',baixas:'Materiais baixados',serv:'Serviços',apropriado:'Custo apropriado',adquirido:'Total adquirido',aguardando:'Aguardando vínculo'};
// ==== #JS-CUSTODIA: END ====
function addTot(t,x){t.entrada+=x.entrada;t.saida+=x.saida;t.pago+=x.pago;t.estoque+=x.estoque;t.serv+=x.serv||0}
// Por projeto × produto: entrada = unidades alocadas das notas; valor pago = unidades × custo unitário pago do item; custo médio = valor pago ÷ entrada; valor em estoque = saldo × custo médio.
function stockTree(){const linhas=new Map();const k=(pid,prod)=>pid+'|'+prod;
 for(const a of state.allocations){const inv=state.invoices.find(i=>i.id===a.invoiceId);if(!inv||isServico(inv))continue;const prod=a.productId||('?'+a.invoiceId+'|'+a.itemIndex);const key=k(a.projectId,prod);if(!linhas.has(key))linhas.set(key,{projectId:a.projectId,productId:prod,entrada:0,saida:0,pago:0});const l=linhas.get(key);l.entrada+=Number(a.quantity);l.pago+=Number(a.quantity)*itemUnitCost(inv,a.itemIndex);if(!l.nome)l.nome=inv.items[a.itemIndex]?.description}
 for(const m of state.movements.filter(m=>m.type==='SAIDA')){const key=k(m.projectId,m.productId);if(!linhas.has(key))linhas.set(key,{projectId:m.projectId,productId:m.productId,entrada:0,saida:0,pago:0});linhas.get(key).saida+=Number(m.quantity)}
 const porProj=new Map();for(const l of linhas.values()){const p=state.products.find(x=>x.id===l.productId);l.produto=p;l.nome=p?.name||l.nome||'Produto';l.saldo=r4(l.entrada-l.saida);l.custo=l.entrada>0?l.pago/l.entrada:0;l.estoque=l.saldo*l.custo;if(!porProj.has(l.projectId))porProj.set(l.projectId,[]);porProj.get(l.projectId).push(l)}
 // Serviços: valor das alocações de notas de serviço, por projeto (custo direto, sem estoque).
 const servPorProj=new Map();for(const a of state.allocations){const inv=state.invoices.find(i=>i.id===a.invoiceId);if(!inv||!isServico(inv))continue;servPorProj.set(a.projectId,(servPorProj.get(a.projectId)||0)+Number(a.quantity)*itemUnitCost(inv,a.itemIndex))}
 const clientes=[...state.clients].sort(byName).map(c=>{const projetos=projectsOf(c.id).map(p=>{const itens=(porProj.get(p.id)||[]).sort((a,b)=>a.nome.localeCompare(b.nome,'pt-BR'));const tot=emptyTot();itens.forEach(l=>addTot(tot,l));tot.serv=servPorProj.get(p.id)||0;return {p,itens,tot}});const tot=emptyTot();projetos.forEach(x=>addTot(tot,x.tot));return {c,projetos,tot}});
 const total=emptyTot();clientes.forEach(x=>addTot(total,x.tot));
 const pend={notas:0,entrada:0,pago:0};state.invoices.filter(inv=>!isServico(inv)).forEach(inv=>{let teve=false;(inv.items||[]).forEach((it,j)=>{const livre=Number(it.quantity)-allocatedQty(inv.id,j);if(livre>1e-9){teve=true;pend.entrada+=livre;pend.pago+=livre*itemUnitCost(inv,j)}});if(teve)pend.notas++});
 const pendServ={notas:0,valor:0};state.invoices.filter(isServico).forEach(inv=>{let teve=false;(inv.items||[]).forEach((it,j)=>{const livre=Number(it.quantity)-allocatedQty(inv.id,j);if(livre>1e-6){teve=true;pendServ.valor+=livre*itemUnitCost(inv,j)}});if(teve)pendServ.notas++});
 return {clientes,total,pend,pendServ}}
function stockCells(t){const saldo=r4(t.entrada-t.saida);return `<td class="num">${num(t.entrada)}</td><td class="num">${t.saida?num(t.saida):'<span class="muted">0</span>'}</td><td class="num"><strong>${num(saldo)}</strong></td><td class="num">${money(t.pago)}</td><td class="num"><strong>${money(t.estoque)}</strong></td>`}
function renderStock(){const root=$('#stockTable');if(!root)return;const q=norm($('#stockSearch')?.value||'');const {clientes,total,pend}=stockTree();
 const casa=(...txt)=>!q||norm(txt.join(' ')).includes(q);
 const rows=[];for(const {c,projetos,tot} of clientes){const cMatch=casa(c.name,c.doc);const projVis=projetos.map(x=>{const pMatch=cMatch||casa(x.p.name);const itens=x.itens.filter(l=>pMatch||casa(l.nome,l.produto?.barcode,l.produto?.code));return {...x,itensVis:itens,show:pMatch||itens.length>0}}).filter(x=>x.show);if(q&&!cMatch&&!projVis.length)continue;
  const aberto=q?true:!collapsedClients.has(c.id);
  rows.push(`<tr class="lv-client" data-toggle-client="${esc(c.id)}"><td><span class="caret">${aberto?'▾':'▸'}</span><strong>${esc(c.name)}</strong> <span class="hint">${projetos.length} projeto(s)</span></td><td></td>${stockCells(tot)}<td></td></tr>`);
  if(!aberto)continue;
  if(!projVis.length)rows.push(`<tr class="lv-project"><td colspan="8" class="muted">Nenhum projeto. Cadastre em Projetos.</td></tr>`);
  for(const x of projVis){const pa=q?x.itensVis.length>0:openProjects.has(x.p.id);
   rows.push(`<tr class="lv-project" data-toggle-project="${esc(x.p.id)}"><td><span class="caret">${x.itens.length?(pa?'▾':'▸'):'·'}</span><span class="dot" style="background:${esc(projColor(x.p))}"></span>${esc(x.p.name)}${x.p.status==='encerrado'?' <span class="pill gray">encerrado</span>':''} <span class="hint">${x.itens.length} produto(s)</span></td><td></td>${stockCells(x.tot)}<td></td></tr>`);
   if(pa)for(const l of x.itensVis){rows.push(`<tr class="lv-product" data-prod-row="${esc(x.p.id)}|${esc(l.productId)}"><td>${esc(l.nome)}<div class="hint">${esc(l.produto?.barcode||l.produto?.code||'')}${l.custo?' · custo médio '+money(l.custo):''}</div></td><td>${esc(l.produto?.unit||'UN')}</td>${stockCells(l)}<td>${l.saldo>1e-9&&l.produto?`<button class="btn sm" data-saida="${esc(x.p.id)}|${esc(l.productId)}">Registrar saída</button>`:''}</td></tr>`)}}}
 rows.push(`<tr class="lv-total"><td>TOTAL DO ESTOQUE</td><td></td>${stockCells(total)}<td></td></tr>`);
 if(pend.notas)rows.push(`<tr class="lv-pending"><td>Aguardando vínculo <span class="hint">(${pend.notas} nota(s), fora do total)</span></td><td></td><td class="num">${num(pend.entrada)}</td><td class="num">—</td><td class="num">${num(pend.entrada)}</td><td class="num">${money(pend.pago)}</td><td class="num">${money(pend.pago)}</td><td><button class="btn sm" data-go-pending>Vincular notas</button></td></tr>`);
 $('#stockCount').textContent=clientes.length+' cliente(s) · '+state.projects.length+' projeto(s)';
 root.innerHTML=state.clients.length||pend.notas?`<div class="tablewrap"><table class="no-sort tree"><thead><tr><th>Cliente / projeto / produto</th><th>Unid.</th><th class="num">Qtd entrada</th><th class="num">Qtd saída</th><th class="num">Saldo</th><th class="num" title="Valor das unidades que entraram (custo de aquisição, com frete e impostos rateados)">Valor de entrada</th><th class="num" title="Saldo × custo médio: valor sob custódia, ainda não apropriado como custo">Valor em estoque</th><th></th></tr></thead><tbody>${rows.join('')}</tbody></table></div>`:tableEmpty('Cadastre clientes e projetos e vincule as notas para ver o estoque por projeto.')}
// ---------- Notas: situação, barra de distribuição e vínculo ----------
let invoiceTab='', selectedInvoiceId='';
function invoiceShares(inv){const porProj=new Map();state.allocations.filter(a=>a.invoiceId===inv.id).forEach(a=>porProj.set(a.projectId,(porProj.get(a.projectId)||0)+Number(a.quantity)*itemUnitCost(inv,a.itemIndex)));const total=(inv.items||[]).reduce((s,it,j)=>s+itemPaid(inv,j),0);const partes=[...porProj].map(([pid,valor])=>({p:projectById(pid),valor}));return {total,partes,livre:Math.max(0,total-partes.reduce((s,x)=>s+x.valor,0))}}
function distBar(sh,big){const t=sh.total||1;return `<div class="dbar${big?' big':''}" title="${esc(sh.partes.map(x=>(x.p?.name||'?')+': '+money(x.valor)).concat(sh.livre>0.005?['Livre: '+money(sh.livre)]:[]).join(' · '))}">${sh.partes.map(x=>`<span style="width:${(x.valor/t*100).toFixed(2)}%;background:${esc(projColor(x.p))}"></span>`).join('')}</div>`}
function projectLabel(p){const c=clientById(p?.clientId);return (c?c.name+' · ':'')+(p?.name||'Projeto removido')}
function projectOptions(sel){const cs=[...state.clients].sort(byName);return cs.map(c=>{const ps=projectsOf(c.id).filter(p=>(p.status!=='encerrado'||p.id===sel)&&(p.id===sel||podeGravarProjeto(p.id)));return ps.length?`<optgroup label="${esc(c.name)}">${ps.map(p=>`<option value="${esc(p.id)}"${p.id===sel?' selected':''}>${esc(p.name)}</option>`).join('')}</optgroup>`:''}).join('')}
let invoiceTipo='todos';
const tipoPill=i=>isServico(i)?'<span class="pill serv">Serviço</span>':'<span class="pill mat">Materiais</span>';
function renderInvoices(){const doTipo=state.invoices.filter(i=>invoiceTipo==='todos'||(invoiceTipo==='servico')===isServico(i));const counts={a_vincular:0,parcial:0,vinculada:0};doTipo.forEach(i=>counts[invoiceStatus(i)]++);if(!invoiceTab)invoiceTab=counts.a_vincular?'a_vincular':counts.parcial?'parcial':'todas';
 $('#invoiceTabs').innerHTML=[['a_vincular','A vincular'],['parcial','Em distribuição'],['vinculada','Vinculadas'],['todas','Todas']].map(([k,l])=>`<button data-inv-tab="${k}" class="${invoiceTab===k?'active':''}">${l}<span class="count${k==='a_vincular'&&counts[k]?' alert':''}">${k==='todas'?doTipo.length:counts[k]}</span></button>`).join('')+'<span class="tabs-sep"></span>'+[['todos','Todas as notas'],['material','Materiais'],['servico','Serviços']].map(([k,l])=>`<button data-inv-tipo="${k}" class="tipo-chip ${k} ${invoiceTipo===k?'active':''}">${l}<span class="count">${k==='todos'?state.invoices.length:state.invoices.filter(i=>(k==='servico')===isServico(i)).length}</span></button>`).join('');
 const q=norm($('#invoiceSearch')?.value||'');const list=[...doTipo].sort((a,b)=>String(b.date).localeCompare(String(a.date))).filter(i=>(invoiceTab==='todas'||invoiceStatus(i)===invoiceTab)&&norm([i.number,i.issuer,i.key,i.source].join(' ')).includes(q));
 $('#invoiceTable').innerHTML=list.length?'<div class="tablewrap"><table><thead><tr><th>Tipo</th><th>Data</th><th>NF / série</th><th>Emitente / prestador</th><th class="num">Itens</th><th class="num">Total</th><th>Situação</th><th>Distribuição</th><th>Ação</th></tr></thead><tbody>'+list.map(i=>{const st=invoiceStatus(i);return `<tr class="${i.id===selectedInvoiceId?'product-editing':''}"><td>${tipoPill(i)}</td><td>${esc(i.date)}</td><td>${esc(i.number)}${i.series?' / '+esc(i.series):''}</td><td>${esc(i.issuer)}<div class="hint">${esc(i.key)}</div></td><td class="num">${i.items.length}</td><td class="num">${money(i.total)}</td><td><span class="pill ${st==='a_vincular'?'warn':st==='parcial'?'blue':''}">${STATUS_LABEL[st]}</span></td><td>${distBar(invoiceShares(i))}</td><td><button class="btn sm ${st==='vinculada'?'':'primary'}" data-open-invoice="${esc(i.id)}">${st==='a_vincular'?'Vincular':st==='parcial'?'Distribuir':'Ver vínculo'}</button></td></tr>`}).join('')+'</tbody></table></div>':tableEmpty(state.invoices.length?'Nenhuma nota nesta situação.':'Nenhuma nota importada.');
 renderDistPanel()}
// Confere se uma nova distribuição da nota deixaria algum projeto com saída maior que a entrada do produto.
function checkSaidas(invId,novas){const chave=(pid,prod)=>pid+'|'+prod;const ent=new Map();state.allocations.filter(a=>a.invoiceId!==invId).concat(novas).forEach(a=>{const k=chave(a.projectId,a.productId);ent.set(k,(ent.get(k)||0)+Number(a.quantity))});for(const m of state.movements.filter(m=>m.type==='SAIDA')){const k=chave(m.projectId,m.productId);const sai=state.movements.filter(x=>x.type==='SAIDA'&&chave(x.projectId,x.productId)===k).reduce((s,x)=>s+Number(x.quantity),0);if((ent.get(k)||0)+1e-9<sai){const p=state.products.find(p=>p.id===m.productId);return `O projeto ${projectLabel(projectById(m.projectId))} já registrou saída de ${num(sai)} ${esc(p?.unit||'')} de "${esc(p?.name||'produto')}"; a distribuição deixaria menos que isso.`}}return ''}
// Grava a distribuição com o escopo de acesso (js/escopo.js): rateios inalterados mantêm o id; nota, projeções e entradas acompanham.
async function saveInvoiceAllocations(inv,novas){if(inv._parcial)throw new Error('Você vê apenas o rateio dos seus projetos nesta nota; a distribuição só pode ser alterada por quem tem acesso a todos os projetos dela.');const erro=checkSaidas(inv.id,novas);if(erro)throw new Error(erro);const antigas=state.allocations.filter(a=>a.invoiceId===inv.id);
 const chave=a=>a.itemIndex+'|'+a.projectId,velhas=new Map(antigas.map(a=>[chave(a),a]));novas=novas.map(a=>{const v=velhas.get(chave(a));return v?{...v,quantity:a.quantity}:a});
 await txWrite(STORES_DIST,os=>escopoGravarNota(os,inv,novas,antigas));await refresh()}
// Nota de compra coletiva vista só pelo rateio dos projetos do usuário: consulta, sem edição.
function distParcialHtml(inv){const sh=invoiceShares(inv),serv=isServico(inv);const itens=inv.items.map((it,j)=>it._oculto?'':`<tr><td>${esc(it.description)}</td><td class="num">${serv?'—':num(it.quantity)+' '+esc(it.unit||'')}</td><td class="num">${money(itemPaid(inv,j))}</td></tr>`).join('');
 return `<div class="dist-panel"><div class="row" style="justify-content:space-between"><div><h3>${tipoPill(inv)} ${serv?'NFS-e':'NF'} ${esc(inv.number)} · ${esc(inv.issuer)}</h3><div class="hint">${esc(inv.date)} · rateio dos seus projetos ${money(sh.total)}</div></div><span class="row" style="gap:6px">${inv.capturaId?`<button class="btn sm" data-nota-fotos="${esc(inv.id)}" title="Mostra as fotos enviadas pela obra: comprovante de recebimento">Fotos da obra</button>`:''}${consultaBotao(inv.consultaUrl)}<button class="btn sm" data-close-invoice title="Fecha o painel desta nota">Fechar</button></span></div><div id="notaFotosObra"></div>
 <div class="notice" style="margin-top:12px">Esta nota foi distribuída também entre projetos aos quais você não tem acesso. Aqui aparecem apenas os itens e valores rateados aos seus projetos; a distribuição só pode ser alterada por quem tem acesso a todos os projetos dela.</div>
 <div style="margin:14px 0 4px">${distBar(sh,true)}</div><div class="legend">${sh.partes.map(x=>`<span><span class="dot" style="background:${esc(projColor(x.p))}"></span>${esc(x.p?.name||'?')} ${money(x.valor)}</span>`).join('')}</div>
 <div class="tablewrap" style="margin-top:14px"><table class="no-sort"><thead><tr><th>Item</th><th class="num">${serv?'':'Quantidade nos seus projetos'}</th><th class="num">Valor pago</th></tr></thead><tbody>${itens}</tbody></table></div></div>`}
function makeAlloc(inv,j,pid,quantity){const p=projectById(pid);return {id:uid(),invoiceId:inv.id,itemIndex:j,productId:inv.items[j].productId||'',projectId:pid,clientId:p?.clientId||'',quantity:Math.round(Number(quantity)*1e8)/1e8,createdAt:new Date().toISOString()}}
function distMsg(html,tipo=''){const el=$('#distMsg');if(el)el.innerHTML=html?`<div class="notice ${tipo}">${html}</div>`:''}
function renderDistPanel(){const root=$('#distPanel');const inv=state.invoices.find(i=>i.id===selectedInvoiceId);if(!inv){root.innerHTML='';return}
 if(inv._parcial){root.innerHTML=distParcialHtml(inv);return}const sh=invoiceShares(inv),st=invoiceStatus(inv);const serv=isServico(inv);const resumo=sh.partes.map(x=>{const qtd=state.allocations.filter(a=>a.invoiceId===inv.id&&a.projectId===x.p?.id).reduce((s,a)=>s+Number(a.quantity),0);return `<tr><td><span class="dot" style="background:${esc(projColor(x.p))}"></span>${esc(projectLabel(x.p))}</td><td class="num">${serv?'—':num(qtd)}</td><td class="num">${money(x.valor)}</td><td class="num">${(x.valor/(sh.total||1)*100).toFixed(1).replace('.',',')}%</td><td><button class="btn sm danger-btn" data-unlink="${esc(x.p?.id||'')}">Desvincular</button></td></tr>`}).join('');
 root.innerHTML=`<div class="dist-panel"><div class="row" style="justify-content:space-between"><div><h3>${tipoPill(inv)} ${serv?'NFS-e':'NF'} ${esc(inv.number)} · ${esc(inv.issuer)}</h3><div class="hint">${esc(inv.date)} · ${inv.items.length} item(ns) · valor pago ${money(sh.total)} · <span class="pill ${st==='a_vincular'?'warn':st==='parcial'?'blue':''}">${STATUS_LABEL[st]}</span></div></div><span class="row" style="gap:6px">${inv.capturaId?`<button class="btn sm" data-nota-fotos="${esc(inv.id)}" title="Mostra as fotos enviadas pela obra: comprovante de recebimento">Fotos da obra</button>`:''}${consultaBotao(inv.consultaUrl)}<button class="btn sm" data-close-invoice title="Fecha o painel desta nota">Fechar</button></span></div><div id="notaFotosObra"></div>
 <div style="margin:14px 0 4px">${distBar(sh,true)}</div><div class="legend">${sh.partes.map(x=>`<span><span class="dot" style="background:${esc(projColor(x.p))}"></span>${esc(x.p?.name||'?')} ${money(x.valor)}</span>`).join('')}${sh.livre>0.005?`<span><span class="dot free"></span>Livre ${money(sh.livre)}</span>`:''}</div>
 ${state.projects.some(p=>p.status!=='encerrado')?`<div class="row" style="margin-top:16px;align-items:flex-end"><div class="field" style="max-width:420px"><label for="quickProject">Vincular ${st==='a_vincular'?'a nota inteira':'todo o restante'} a um projeto</label><select id="quickProject"><option value="">Escolha cliente · projeto…</option>${projectOptions()}</select></div><button class="btn primary" id="quickLink"${st==='vinculada'?' disabled':''}>Vincular</button></div>`:`<div class="notice">Cadastre um cliente e um projeto para vincular esta nota.</div>`}
 <div id="distMsg"></div>${resumo?`<div class="tablewrap alloc-list" style="margin-top:14px"><table style="min-width:520px"><thead><tr><th>Cliente · projeto</th><th class="num">${serv?'':'Unidades'}</th><th class="num">Valor pago</th><th class="num">Parte</th><th></th></tr></thead><tbody>${resumo}</tbody></table></div>`:''}<div id="distMatrix"></div></div>`;renderDistMatrix(inv)}
// ---------- Distribuição de compra coletiva: matriz item × projeto ----------
let distDraft=null;
function draftFromAllocations(inv){const q={},cols=[];state.allocations.filter(a=>a.invoiceId===inv.id).forEach(a=>{if(!cols.includes(a.projectId))cols.push(a.projectId);q[a.itemIndex+'|'+a.projectId]=(q[a.itemIndex+'|'+a.projectId]||0)+Number(a.quantity)});return {invId:inv.id,cols,q,dirty:false}}
const r4=n=>Math.round(n*10000)/10000;const r8=n=>Math.round(n*1e8)/1e8;
function draftRow(inv,j){const usado=distDraft.cols.reduce((s,pid)=>s+Number(distDraft.q[j+'|'+pid]||0),0),qtd=Number(inv.items[j].quantity),tol=isServico(inv)?0.005/Math.max(itemUnitCost(inv,j),0.01):1e-9;return {usado,qtd,resto:Math.abs(qtd-usado)<tol?0:Math.round((qtd-usado)*1e8)/1e8,excesso:usado>qtd+tol}}
function draftShares(inv){const partes=distDraft.cols.map(pid=>({p:projectById(pid),valor:inv.items.reduce((s,it,j)=>s+Number(distDraft.q[j+'|'+pid]||0)*itemUnitCost(inv,j),0),qtd:inv.items.reduce((s,it,j)=>s+Number(distDraft.q[j+'|'+pid]||0),0)}));const total=inv.items.reduce((s,it,j)=>s+itemPaid(inv,j),0);return {total,partes:partes.filter(x=>x.valor>0),todas:partes,livre:Math.max(0,total-partes.reduce((s,x)=>s+x.valor,0))}}
function miniBar(inv,j){const qtd=Number(inv.items[j].quantity)||1;const segs=distDraft.cols.map(pid=>{const v=Number(distDraft.q[j+'|'+pid]||0);return v>0?`<span style="width:${Math.min(100,v/qtd*100).toFixed(2)}%;background:${esc(projColor(projectById(pid)))}"></span>`:''}).join('');return `<div class="dbar" style="min-width:90px;height:8px">${segs}</div>`}
function renderDistMatrix(inv){const root=$('#distMatrix');if(!root)return;if(!distDraft||distDraft.invId!==inv.id||!distDraft.dirty)distDraft=draftFromAllocations(inv);const cols=distDraft.cols.map(projectById).filter(Boolean);const livres=state.projects.filter(p=>p.status!=='encerrado'&&!distDraft.cols.includes(p.id));
 root.innerHTML=`<hr style="border:0;border-top:1px solid var(--line);margin:18px 0"><div class="row" style="justify-content:space-between;align-items:flex-end"><div><h3>${isServico(inv)?'Contratação coletiva: dividir o valor entre projetos':'Compra coletiva: distribuir itens entre projetos'}</h3><p class="hint" style="margin:4px 0 0">${isServico(inv)?'Informe quanto do valor (R$) vai para cada projeto. A soma não pode passar do total da nota;':'Informe quantas unidades de cada item vão para cada projeto. A soma por item não pode passar da quantidade da nota;'} o que sobrar continua livre para vincular depois.</p></div><div class="row"><select id="distAddProject" class="inline-input"><option value="">Adicionar cliente · projeto…</option>${projectOptions().replace(/<option value="([^"]+)"/g,(m,id)=>distDraft.cols.includes(id)?m+' disabled':m)}</select><button class="btn sm" id="distAddBtn"${livres.length?'':' disabled'}>＋ Coluna</button></div></div>
 ${cols.length?`<div class="tablewrap" style="margin-top:12px"><table class="dist-table"><thead><tr><th>Item da nota</th>${isServico(inv)?'<th class="num">Valor</th>':'<th class="num">Qtd</th><th class="num">Custo unit.</th>'}${cols.map(p=>`<th class="num" style="border-top:4px solid ${esc(projColor(p))}"><span class="dot" style="background:${esc(projColor(p))}"></span>${esc(p.name)}<div class="hint" style="text-transform:none;letter-spacing:0">${esc(clientById(p.clientId)?.name||'')} <button class="btn sm" data-dist-rm="${esc(p.id)}" title="Tirar esta coluna" style="padding:0 6px;margin-left:4px">✕</button></div></th>`).join('')}<th>Restante</th></tr></thead><tbody>${inv.items.map((it,j)=>`<tr data-dist-row="${j}"><td>${esc(it.description)}<div class="hint">${esc(it.unit||'')}</div></td>${isServico(inv)?`<td class="num">${money(itemPaid(inv,j))}</td>`:`<td class="num">${num(it.quantity)}</td><td class="num">${money(itemUnitCost(inv,j))}</td>`}${cols.map(p=>`<td class="num"><input type="number" min="0" step="any" data-dq="${j}|${esc(p.id)}" value="${distDraft.q[j+'|'+p.id]?(isServico(inv)?(distDraft.q[j+'|'+p.id]*itemUnitCost(inv,j)).toFixed(2):r4(distDraft.q[j+'|'+p.id])):''}"${isServico(inv)?' data-dv="1"':''} placeholder="0" style="width:84px;padding:6px;text-align:right;border:1px solid #cbd5e1;border-radius:6px"></td>`).join('')}<td data-dist-rest="${j}"></td></tr>`).join('')}</tbody><tfoot><tr style="background:#f8fafc;font-weight:700"><td>Valor por projeto</td>${isServico(inv)?'<td></td>':'<td></td><td></td>'}${cols.map(p=>`<td class="num" data-dist-val="${esc(p.id)}"></td>`).join('')}<td data-dist-free></td></tr></tfoot></table></div>
 <div class="row" style="margin-top:12px"><button class="btn sm" id="distEqual">Distribuir restante igualmente</button><span class="muted">ou</span><select id="distRestTo" class="inline-input" style="min-width:160px"><option value="">Restante → projeto…</option>${cols.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}</select><button class="btn sm" id="distRestBtn">Aplicar</button><span class="right"></span><button class="btn sm" id="distReset">Descartar alterações</button><button class="btn primary" id="distSave">Salvar distribuição</button></div><div id="distWarn"></div>`:'<p class="muted" style="margin-top:10px">Adicione as colunas dos projetos que dividem esta compra.</p>'}`;
 updateDistMatrix(inv)}
function updateDistMatrix(inv){if(!$('#distMatrix'))return;let algumExcesso=false;inv.items.forEach((it,j)=>{const r=draftRow(inv,j);if(r.excesso)algumExcesso=true;const cel=document.querySelector(`[data-dist-rest="${j}"]`);if(cel)cel.innerHTML=`<div class="row" style="gap:8px;flex-wrap:nowrap">${miniBar(inv,j)}<strong style="color:${r.excesso?'#dc2626':r.resto<=1e-9?'#16a34a':'#475569'};white-space:nowrap">${r.excesso?'excede '+(isServico(inv)?money(-r.resto*itemUnitCost(inv,j)):num(-r.resto)):r.resto<=1e-9?'✓ completo':(isServico(inv)?money(r.resto*itemUnitCost(inv,j)):num(r.resto))+' livre'}</strong></div>`;document.querySelectorAll(`[data-dq^="${j}|"]`).forEach(inp=>inp.style.borderColor=r.excesso?'#dc2626':'#cbd5e1')});
 const sh=draftShares(inv);sh.todas.forEach(x=>{const c=document.querySelector(`[data-dist-val="${x.p?.id}"]`);if(c)c.innerHTML=`${money(x.valor)}<div class="hint">${isServico(inv)?'':num(x.qtd)+' un · '}${(x.valor/(sh.total||1)*100).toFixed(1).replace('.',',')}%</div>`});const f=document.querySelector('[data-dist-free]');if(f)f.innerHTML=`<span class="muted">Livre ${money(sh.livre)}</span>`;
 const big=document.querySelector('#distPanel .dbar.big');if(big)big.outerHTML=distBar(sh,true);const lg=document.querySelector('#distPanel .legend');if(lg)lg.innerHTML=sh.partes.map(x=>`<span><span class="dot" style="background:${esc(projColor(x.p))}"></span>${esc(x.p?.name||'?')} ${money(x.valor)}</span>`).join('')+(sh.livre>0.005?`<span><span class="dot free"></span>Livre ${money(sh.livre)}</span>`:'')+(distDraft.dirty?'<span class="pill warn">prévia não salva</span>':'');
 const sv=$('#distSave');if(sv)sv.disabled=algumExcesso||!distDraft.dirty;const w=$('#distWarn');if(w)w.innerHTML=algumExcesso?'<div class="notice danger">Há itens com mais unidades distribuídas do que a nota possui (em vermelho). Corrija antes de salvar.</div>':''}
function distEqual(inv){const n=distDraft.cols.length;if(!n)return;inv.items.forEach((it,j)=>{const r=draftRow(inv,j);if(r.resto<=1e-9)return;const inteiro=!isServico(inv)&&Number.isInteger(r.resto);const base=inteiro?Math.floor(r.resto/n):r8(r.resto/n);let sobra=r8(r.resto-base*n);distDraft.cols.forEach(pid=>{let add=base;if(sobra>1e-9){const d=inteiro?1:sobra;add=r8(add+d);sobra=r8(sobra-d)}if(add>0)distDraft.q[j+'|'+pid]=r8(Number(distDraft.q[j+'|'+pid]||0)+add)})});distDraft.dirty=true}
async function distSave(inv){const novas=[];for(const [k,v] of Object.entries(distDraft.q)){const [j,pid]=k.split('|');if(!distDraft.cols.includes(pid)||!(Number(v)>0))continue;novas.push(makeAlloc(inv,Number(j),pid,v))}if(inv.items.some((it,j)=>draftRow(inv,j).excesso))throw new Error('A soma distribuída de algum item passa da quantidade da nota.');distDraft.dirty=false;try{await saveInvoiceAllocations(inv,novas)}catch(e){distDraft.dirty=true;throw e}distMsg('Distribuição salva.','success')}
document.addEventListener('input',e=>{const el=e.target.closest('[data-dq]');if(!el||!distDraft)return;const inv=state.invoices.find(i=>i.id===distDraft.invId);let v=Number(String(el.value).replace(',','.'));if(el.dataset.dv){const j=+el.dataset.dq.split('|')[0],u=itemUnitCost(inv,j);v=u>0?v/u:0}distDraft.q[el.dataset.dq]=Number.isFinite(v)&&v>0?v:0;distDraft.dirty=true;updateDistMatrix(inv)});
document.addEventListener('click',e=>{if(!distDraft)return;const inv=state.invoices.find(i=>i.id===distDraft.invId);if(!inv)return;const falha=err=>distMsg(esc(err.message),'danger');
 if(e.target.closest('#distAddBtn')){const pid=$('#distAddProject').value;if(pid&&!distDraft.cols.includes(pid)){distDraft.cols.push(pid);distDraft.dirty=true;renderDistMatrix(inv)}return}
 const rm=e.target.closest('[data-dist-rm]');if(rm){const pid=rm.dataset.distRm;distDraft.cols=distDraft.cols.filter(x=>x!==pid);Object.keys(distDraft.q).forEach(k=>{if(k.endsWith('|'+pid))delete distDraft.q[k]});distDraft.dirty=true;renderDistMatrix(inv);return}
 if(e.target.closest('#distEqual')){distEqual(inv);renderDistMatrix(inv);return}
 if(e.target.closest('#distRestBtn')){const pid=$('#distRestTo').value;if(!pid)return;inv.items.forEach((it,j)=>{const r=draftRow(inv,j);if(r.resto>1e-9)distDraft.q[j+'|'+pid]=r8(Number(distDraft.q[j+'|'+pid]||0)+r.resto)});distDraft.dirty=true;renderDistMatrix(inv);return}
 if(e.target.closest('#distReset')){distDraft=null;renderDistMatrix(inv);return}
 if(e.target.closest('#distSave'))distSave(inv).catch(falha)});
async function quickLink(){const inv=state.invoices.find(i=>i.id===selectedInvoiceId),pid=$('#quickProject').value;if(!inv)return;distDraft=null;if(!pid){distMsg('Escolha o cliente e o projeto.','danger');return}const novas=state.allocations.filter(a=>a.invoiceId===inv.id).map(a=>({...a}));inv.items.forEach((it,j)=>{const resto=Number(it.quantity)-allocatedQty(inv.id,j);if(resto>1e-9){const ex=novas.find(a=>a.itemIndex===j&&a.projectId===pid);if(ex)ex.quantity=Math.round((ex.quantity+resto)*10000)/10000;else novas.push(makeAlloc(inv,j,pid,resto))}});await saveInvoiceAllocations(inv,novas);distMsg('Nota vinculada a '+esc(projectLabel(projectById(pid)))+'.','success')}
async function unlinkProject(pid){const inv=state.invoices.find(i=>i.id===selectedInvoiceId);if(!inv)return;distDraft=null;await saveInvoiceAllocations(inv,state.allocations.filter(a=>a.invoiceId===inv.id&&a.projectId!==pid));distMsg('Vínculo removido; as unidades voltaram a ficar livres.','success')}

function digits(v){return String(v||'').replace(/\D/g,'')}
function formatDoc(v){const d=digits(v);if(d.length===14)return d.replace(/^(\d{2})(\d{3})(\d{3})(\d{4})(\d{2})$/,'$1.$2.$3/$4-$5');if(d.length===11)return d.replace(/^(\d{3})(\d{3})(\d{3})(\d{2})$/,'$1.$2.$3-$4');return v||'Documento não informado'}
function supplierGroups(){const groups=new Map();state.invoices.forEach(inv=>{const doc=digits(inv.issuerDoc)||'SEM-DOC:'+norm(inv.issuer);if(!groups.has(doc))groups.set(doc,{doc,name:inv.issuer||'Fornecedor sem nome',invoices:[],count:0,total:0});const g=groups.get(doc);g.invoices.push(inv);g.count++;g.total+=Number(inv.total||0);if((!g.name||g.name==='Fornecedor sem nome')&&inv.issuer)g.name=inv.issuer});return [...groups.values()].map(g=>({...g,searchText:norm([g.name,g.doc,formatDoc(g.doc.startsWith('SEM-DOC:')?'':g.doc),...g.invoices.flatMap(i=>[i.number,i.series,i.key,i.date,i.source,i.operation,i.total,i.totalProducts,i.discount,i.issuer,i.issuerDoc,...(i.items||[]).flatMap(it=>Object.values(it))])].join(' '))})).sort((a,b)=>a.name.localeCompare(b.name,'pt-BR'))}
function renderSuppliers(){const results=$('#supplierResults');if(!results)return;const q=norm($('#supplierSearch').value||'');const arr=supplierGroups();const matches=q?arr.filter(g=>g.searchText.includes(q)):arr;results.innerHTML=matches.length?`<div class="hint" style="margin-bottom:8px">${matches.length} fornecedor(es) encontrado(s)${q?' para a busca informada':'. Digite uma palavra-chave para pesquisar.'}</div><div class="tablewrap"><table><thead><tr><th>Fornecedor</th><th>CNPJ/CPF</th><th class="num">Notas fiscais</th><th class="num">Valor acumulado</th><th>Ação</th></tr></thead><tbody>${matches.map(g=>`<tr><td><strong>${esc(g.name)}</strong></td><td>${esc(g.doc.startsWith('SEM-DOC:')?'Não informado':formatDoc(g.doc))}</td><td class="num">${g.count}</td><td class="num">${money(g.total)}</td><td><button class="btn ${selectedSupplierDoc===g.doc?'primary':''}" data-open-supplier="${esc(g.doc)}">${selectedSupplierDoc===g.doc?'Fornecedor selecionado':'Ver notas'}</button></td></tr>`).join('')}</tbody></table></div>`:tableEmpty(q?'Nenhum fornecedor encontrado para essa palavra-chave.':'Ainda não há fornecedores. Importe XMLs de NF-e para criar o histórico.');if(selectedSupplierDoc&&!arr.some(g=>g.doc===selectedSupplierDoc))selectedSupplierDoc='';renderSupplierInvoices()}
function renderSupplierInvoices(){const doc=selectedSupplierDoc;const root=$('#supplierInvoices'),summary=$('#supplierSummary');if(!doc){summary.textContent='Selecione “Ver notas” em um fornecedor para listar as notas fiscais e os itens de cada documento.';root.innerHTML='';return}const g=supplierGroups().find(x=>x.doc===doc);if(!g){summary.textContent='Fornecedor não encontrado.';root.innerHTML='';return}const gInvoices=[...g.invoices].sort((a,b)=>String(b.date).localeCompare(String(a.date)));const total=gInvoices.reduce((a,i)=>a+Number(i.total||0),0);summary.innerHTML=`<strong>Fornecedor selecionado: ${esc(g.name)}</strong> · ${esc(formatDoc(doc.startsWith('SEM-DOC:')?'':doc))}<br>${gInvoices.length} nota(s) fiscal(is) · Valor acumulado: <strong>${money(total)}</strong> · ${gInvoices.reduce((a,i)=>a+(i.items||[]).length,0)} linha(s) de produto`;if(!gInvoices.length){root.innerHTML=tableEmpty('Nenhuma nota fiscal registrada para este fornecedor.');return}root.innerHTML=`<div class="row" style="justify-content:space-between;margin:16px 0 8px"><h3 style="margin:0">Notas fiscais do fornecedor</h3><button class="btn" id="clearSupplierSelection">Limpar seleção</button></div>`+gInvoices.map(inv=>`<details class="supplier-invoice" style="border:1px solid var(--line);border-radius:10px;margin:10px 0;background:#fff"><summary style="cursor:pointer;padding:15px;display:flex;gap:12px;align-items:center;flex-wrap:wrap;list-style-position:inside"><strong>NF ${esc(inv.number||'—')} / série ${esc(inv.series||'—')}</strong><span class="muted">${esc(inv.date||'')}</span><span class="tag-muted">${(inv.items||[]).length} item(ns)</span><span class="right"><strong>${money(inv.total)}</strong></span></summary><div style="padding:0 14px 14px"><div class="hint" style="margin-bottom:10px">Chave: ${esc(inv.key||'—')} · Operação: ${esc(inv.operation||'—')} · Arquivo: ${esc(inv.source||'—')}</div><div class="tablewrap"><table style="min-width:650px"><thead><tr><th>Produto / descrição</th><th>Código</th><th>EAN/GTIN</th><th>Unidade</th><th class="num">Quantidade</th><th class="num">Valor unitário</th><th class="num">Total bruto</th><th class="num">Desconto</th></tr></thead><tbody>${(inv.items||[]).map(it=>`<tr><td>${esc(it.description||'')}</td><td>${esc(it.code||'—')}</td><td>${esc(it.barcode||'—')}</td><td>${esc(it.unit||'—')}</td><td class="num"><strong>${num(it.quantity)}</strong></td><td class="num">${money(it.unitPrice)}</td><td class="num">${money(it.lineTotal)}</td><td class="num">${money(it.discount)}</td></tr>`).join('')||'<tr><td colspan="8">Nenhum item registrado nesta nota.</td></tr>'}</tbody></table></div></div></details>`).join('');$('#clearSupplierSelection')?.addEventListener('click',()=>{selectedSupplierDoc='';renderSuppliers()})}
function lastPaid(prodId){let best=null;state.invoices.filter(inv=>!isServico(inv)).forEach(inv=>(inv.items||[]).forEach((it,j)=>{if(it.productId===prodId&&(!best||String(inv.date)>String(best.date)))best={date:inv.date,cost:itemUnitCost(inv,j),supplier:inv.issuer}}));return best}
function renderProducts(){const activeId=$('#editingProductId').value;$('#editingProductLabel').value=state.products.find(p=>p.id===activeId)?.name||'Nenhum produto selecionado';const q=norm($('#productSearch')?.value||'');const list=[...state.products].sort(byName).filter(p=>!q||norm([p.name,p.barcode,p.code].join(' ')).includes(q));$('#productTable').innerHTML=list.length?'<div class="tablewrap"><table><thead><tr><th>Produto</th><th>EAN/GTIN</th><th>Unidade</th><th>Origem</th><th class="num">Último custo pago</th><th class="num">Saldo</th><th>Ações</th></tr></thead><tbody>'+list.map(p=>{const lp=lastPaid(p.id);return `<tr class="${p.id===activeId?'product-editing':''}"><td><strong>${esc(p.name)}</strong><div class="hint">Código interno: ${esc(p.code||'—')}</div></td><td>${esc(p.barcode||'—')}</td><td>${esc(p.unit||'UN')}</td><td>${p.origin==='manual'?'<span class="pill gray">Digitado</span>':'<span class="pill">Nota</span>'}</td><td class="num">${lp?money(lp.cost)+`<div class="hint">${esc(lp.date)} · ${esc(lp.supplier)}</div>`:'—'}</td><td class="num">${num(p.stock)}</td><td style="white-space:nowrap"><button class="btn sm" data-quote-add="${esc(p.id)}">＋ Orçamento</button> <button class="btn sm ${p.id===activeId?'primary':''}" data-edit-product="${esc(p.id)}">Editar</button></td></tr>`}).join('')+'</tbody></table></div>':tableEmpty(state.products.length?'Nenhum produto encontrado.':'O catálogo é formado pelas notas importadas e pelos itens digitados.');renderQuote()}
